#!/usr/bin/env bash
# =====================================================================
# dysflow-plugin:user-prompt-submit v2.31.0
# =====================================================================
# This file is GENERATED by the dysflow plugin. DO NOT EDIT MANUALLY.
# On plugin update, this file is replaced.
# =====================================================================
# Fires on every user prompt. Detects the worktree-bootstrap friction:
# if the cwd is a git worktree without .dysflow/ AND a sibling worktree
# has one, surface the bootstrap command so the agent doesn't invent it.
# Silent when .dysflow/ exists. No noise in the common case.
# =====================================================================
set -euo pipefail

# Already configured -> nothing to say.
if [ -d .dysflow ]; then
    exit 0
fi

# Not a git worktree -> not a dysflow target -> nothing to say.
if [ ! -d .git ] && [ ! -f .git ]; then
    exit 0
fi

# Find sibling worktrees with .dysflow/ (best-effort, no git binary required for this check).
sibling=""
for path in ../*/.dysflow; do
    if [ -d "$path" ]; then
        sibling="$(dirname "$path")"
        break
    fi
done

if [ -n "$sibling" ]; then
    echo "[dysflow-plugin v2.31.0] Detected git worktree without .dysflow/."
    echo "  Sibling worktree:  $sibling"
    echo "  Bootstrap:         dysflow setup --cwd $(pwd) --apply --access-path <sibling-accessPath>"
fi

exit 0
